  polite:[{ask:"Dein Zimmer ist kalt. Wie sagst du das an der Rezeption am besten?", o:["I'm sorry to bother you, but the heating doesn't seem to be working.","The heating is broken. Fix it.","Your hotel is terrible.","Why is it so cold here?"], a:0}],
  tip:{t:"Höflich beschweren – very British", d:"Engländer mildern Beschwerden ab: „I'm afraid …“ (leider), „doesn't seem to …“ (scheint nicht zu …), „Would it be possible …?“ (Wäre es möglich …?). Direkte Sätze wirken schnell unhöflich.",
    ex:[["I'm afraid there's a problem.","Leider gibt es ein Problem."],["The Wi-Fi doesn't seem to work.","Das WLAN scheint nicht zu gehen."],["Would it be possible to have more towels?","Wäre es möglich, mehr Handtücher zu bekommen?"]]}
